using UnityEngine;

namespace ToastalRecall
{
    /// <summary>
    /// Marks a Canvas that was generated by Tools > Toastal Recall > Rebuild All UI.
    /// The marker lets the editor builder find and rebuild its own Canvas without
    /// touching hand-made UI. It has no runtime behaviour; delete it if you want to
    /// keep a Canvas exactly as-is (the builder will then leave that scene alone only
    /// until you run a manual rebuild).
    /// </summary>
    public class EditableUICanvas : MonoBehaviour
    {
        [Tooltip("Stable id used by the editor builder (for example: main-menu).")]
        public string layoutId = "main-menu";

        [Tooltip("Version of the baked layout. Raise it if a future update should refresh this Canvas.")]
        public int layoutVersion = 1;
    }
}
